"""Client addresses (docs/ratelimit.md, section 7)."""

import ipaddress


def parse_address(text):
    text = text.strip(" \t")
    if text.startswith("["):
        end = text.find("]")
        if end < 0:
            return None
        rest = text[end + 1:]
        if rest and not (rest.startswith(":") and rest[1:].isascii() and rest[1:].isdigit()):
            return None
        host = text[1:end]
        if ":" not in host:
            return None
    elif text.count(":") == 1:
        host, port = text.split(":")
        if not (port.isascii() and port.isdigit()):
            return None
    else:
        host = text
    if "%" in host or "/" in host or not host.isascii():
        return None
    try:
        addr = ipaddress.ip_address(host)
    except ValueError:
        return None
    if addr.version == 6 and addr.ipv4_mapped is not None:
        return addr.ipv4_mapped
    return addr


def in_any(addr, networks) -> bool:
    return any(addr.version == net.version and addr in net for net in networks)


def client_address(request, trusted):
    peer = parse_address(request.peer)
    if peer is None or not in_any(peer, trusted):
        return peer if peer is not None else request.peer
    entries = []
    for value in request.headers.get_all("X-Forwarded-For"):
        entries.extend(part.strip(" \t") for part in value.split(","))
    if not entries:
        return peer
    previous = peer
    for entry in reversed(entries):
        addr = parse_address(entry)
        if addr is None:
            return previous
        if not in_any(addr, trusted):
            return addr
        previous = addr
    return parse_address(entries[0])


def key_text(addr) -> str:
    if isinstance(addr, str):
        return addr
    if addr.version == 4:
        return str(addr)
    return str(ipaddress.ip_network((addr, 64), strict=False))
