"""Stage 3: rate limits (docs/ratelimit.md)."""

import math

from frontdoor.ratelimit.address import client_address, in_any, key_text
from frontdoor.ratelimit.state import new_state

NAME = "ratelimit"


class State:
    def __init__(self, config):
        self.limits = config.section("limit", [])
        self.trusted = config.section("clients", ())
        self.buckets = [{} for _ in self.limits]
        self.refused = {limit.name: 0 for limit in self.limits}
        self.clock = None


def setup(config):
    return State(config)


def key_value(part, ctx, address):
    if part == "tenant":
        return ctx.tenant
    if part == "client":
        return key_text(address)
    if part == "route":
        return ctx.route.name
    if part == "method":
        return ctx.request.method.upper()
    value = ctx.request.headers.get(part[len("header:"):])
    if value is None:
        return None
    return value.strip(" \t") or None


def handle(ctx, state):
    if not state.limits:
        return None
    request = ctx.request
    now = request.ts_ms if state.clock is None else max(state.clock, request.ts_ms)
    state.clock = now
    method = request.method.upper()
    address = client_address(request, state.trusted)
    covering = []
    for index, limit in enumerate(state.limits):
        if limit.routes is not None and ctx.route.name not in limit.routes:
            continue
        if limit.methods is not None and method not in limit.methods:
            continue
        if address is not None and not isinstance(address, str) and in_any(address, limit.exempt):
            continue
        key = tuple(key_value(part, ctx, address) for part in limit.key)
        if any(value is None for value in key):
            continue
        slots = state.buckets[index]
        entry = slots.get(key)
        if entry is None:
            entry = slots[key] = new_state(limit, now)
        entry.refill(now)
        covering.append((limit, entry, limit.cost_of(method)))
    if not covering:
        return None
    refusing = [(limit, entry, cost) for limit, entry, cost in covering
                if cost > limit.capacity or not entry.allows(cost)]
    if not refusing:
        for _, entry, cost in covering:
            entry.charge(cost)
        _, deciding, _ = min(covering, key=lambda item: item[1].remaining())
        _headers(ctx, deciding, now)
        return None
    best = None
    for limit, entry, cost in refusing:
        over = cost > limit.capacity
        wait = None if over else entry.wait(cost, now)
        state.refused[limit.name] += 1
        if best is None or (over and not best[0]) or (
                over == best[0] and not over and wait > best[1]):
            best = (over, wait, entry)
    over, wait, entry = best
    _headers(ctx, entry, now)
    if not over:
        ctx.headers["Retry-After"] = str(max(1, math.ceil(wait / 1000)))
    return 429


def _headers(ctx, entry, now):
    ctx.headers["RateLimit-Limit"] = str(entry.limit.capacity)
    ctx.headers["RateLimit-Remaining"] = str(entry.remaining())
    ctx.headers["RateLimit-Reset"] = str(entry.reset(now))


def summary(state):
    if not state.limits:
        return {}
    return {"rl_refused": dict(state.refused)}
